<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { RouterView, useRoute, useRouter } from 'vue-router'
import { NButton, NConfigProvider, NMessageProvider, NPopover, NTooltip, zhCN, dateZhCN } from 'naive-ui'
import { useSession } from '../shared/auth/store'
import { humanError } from '../shared/api/client'
import { navigation } from './navigation'
import { environment, loadEnvironment } from '../shared/environment'
import Icon from '../shared/ui/Icon.vue'
const session=useSession(),route=useRoute(),router=useRouter(),mobile=ref(false),search=ref(''),error=ref('')
const isAuth=computed(()=>route.path==='/login')
const theme={common:{primaryColor:'#2367ed',primaryColorHover:'#397bf1',primaryColorPressed:'#1857ce',borderRadius:'5px',fontSize:'13px',fontFamily:'"Microsoft YaHei", "PingFang SC", system-ui, sans-serif',textColorBase:'#17233b',borderColor:'#e6edf5'}}
async function retry(){error.value='';try{await session.restore();await router.replace(session.user?'/dashboard':'/login')}catch(e){error.value=humanError(e)}}
async function logout(){try{await session.logout();await router.push('/login')}catch(e){error.value=humanError(e)}}
function expired(){session.user=null;void router.replace('/login')}
function searchSources(){void router.push({path:'/sources',query:search.value?{q:search.value}:{}});mobile.value=false}
function keyboard(event:KeyboardEvent){if((event.ctrlKey||event.metaKey)&&event.key==='k'){event.preventDefault();document.querySelector<HTMLInputElement>('.global-search input')?.focus()}}
onMounted(()=>{void loadEnvironment();window.addEventListener('vision-session-expired',expired);window.addEventListener('keydown',keyboard)})
onUnmounted(()=>{window.removeEventListener('vision-session-expired',expired);window.removeEventListener('keydown',keyboard)})
</script>
<template><NConfigProvider :theme-overrides="theme" :locale="zhCN" :date-locale="dateZhCN"><NMessageProvider><div v-if="environment?.data_origin==='mock'" class="demo-mode-banner" role="status">演示模式 · 所有运行、画面、报警和导出均为模拟，不代表真实识别效果</div><template v-if="!session.ready"><main class="auth-card-wrap" style="min-height:100vh"><section class="panel"><h2>连接本机服务</h2><p class="muted" style="margin:12px 0">{{error||'正在检查工作空间，请稍候。'}}</p><NButton @click="retry">重新连接</NButton></section></main></template><RouterView v-else-if="isAuth"/><div v-else class="app-shell" :class="{'demo-mode':environment?.data_origin==='mock'}"><div class="scrim" :class="{visible:mobile}" @click="mobile=false"/><aside class="sidebar" :class="{open:mobile}" aria-label="主导航"><RouterLink to="/dashboard" class="brand"><span class="brand-mark"/>视觉监测验证</RouterLink><nav class="nav-list"><template v-for="item in navigation" :key="item.label"><NTooltip v-if="item.disabled" trigger="hover"><template #trigger><span><button class="nav-entry" disabled><Icon :name="item.icon"/>{{item.label}}<span class="later">稍后</span></button></span></template>此模块将在后续版本接入</NTooltip><RouterLink v-else :to="item.path!" class="nav-entry" @click="mobile=false"><Icon :name="item.icon"/>{{item.label}}</RouterLink></template></nav><div class="sidebar-foot"><span><span class="dot"/>本地部署工作空间</span><div>基础版本 · 视觉验证平台</div></div></aside><header class="topbar"><button class="icon-button mobile-toggle" aria-label="展开导航" @click="mobile=!mobile"><Icon name="menu"/></button><form class="global-search" @submit.prevent="searchSources"><Icon name="search" :size="17"/><input v-model="search" aria-label="搜索视频源" placeholder="搜索视频源名称或地址…"/><kbd>Ctrl K</kbd></form><div class="top-actions"><NPopover trigger="click" placement="bottom-end"><template #trigger><button class="icon-button" aria-label="通知"><Icon name="bell"/></button></template><div style="width:245px;padding:8px"><strong>工作空间通知</strong><p style="font-size:12px;color:#78859a;margin-top:8px">当前没有新的通知。事件记录请在快速监控看板查看。</p></div></NPopover><div class="user"><div class="avatar">{{session.user?.username.slice(0,1).toUpperCase()}}</div><div>{{session.user?.username}}<small>{{session.user?.role==='admin'?'系统管理员':session.user?.role==='operator'?'操作员':'只读用户'}}</small></div></div><button class="icon-button" aria-label="退出登录" title="退出登录" @click="logout"><Icon name="logout" :size="17"/></button></div></header><main class="workspace"><div v-if="error" class="error-banner" role="alert">{{error}}</div><RouterView/></main></div></NMessageProvider></NConfigProvider></template>
